// Styling for the reusable property card.
//
// This card is the load-bearing piece of the property UI: the same component
// will serve Featured Properties, Recent Properties, Similar Properties and
// Search Results, in a carousel or in a plain grid. So it carries no carousel
// assumptions — it fills whatever box it is given, at full height.
//
// Two things guarantee the "all cards align" requirement:
//
// 1. The media box is a fixed aspect ratio, so no photograph can make one card
//    taller than its neighbour regardless of the source dimensions.
// 2. The card is a full-height flex column and the footer is pushed down with
//    margin-top: auto, so rent and CTA sit on a common baseline even when one
//    title wraps differently. Title and location are clamped to one line each.

import template1 from "./template-1";

export type PropertyCardLabels = {
  featured: string;
  /** Suffix after the rent figure. */
  rentPeriod: string;
  cta: string;
  bedsOne: string;
  bedsMany: string;
  /** Shown instead of "0 Beds" when bedrooms is zero. */
  studio: string;
  bathsOne: string;
  bathsMany: string;
  /** `{n}` is replaced by the formatted area. */
  area: string;
};

export type PropertyCardTemplate = {
  css: string;
  rootClass: string;
  labels: PropertyCardLabels;
  layout: typeof template1.layout;
};

const { color, layout, spacing, timing, typography } = template1;

const ease = "cubic-bezier(.22, 1, .36, 1)";

const labels: PropertyCardLabels = {
  featured: "Featured",
  rentPeriod: "/ month",
  cta: "View",
  bedsOne: "Bed",
  bedsMany: "Beds",
  studio: "Studio",
  bathsOne: "Bath",
  bathsMany: "Baths",
  area: "{n} sq ft",
};

const css = `
.kr-pcard {
  position: relative;
  display: flex;
  flex-direction: column;
  height: 100%;
  background: ${color.background};
  border: 1px solid ${color.border};
  border-radius: ${layout.radius}px;
  box-shadow: ${color.shadow};
  overflow: hidden;
  transition:
    border-color ${timing.hover}ms ${ease},
    box-shadow ${timing.hover}ms ${ease},
    transform ${timing.hover}ms ${ease};
}
.kr-pcard:hover {
  border-color: ${color.borderHover};
  box-shadow: ${color.shadowHover};
  transform: translateY(${layout.lift}px);
}
/* The whole card is one link target, so the focus ring belongs on the card. */
.kr-pcard:focus-within {
  border-color: ${color.focus};
  box-shadow: 0 0 0 2px ${color.focus};
}

/* ── media ────────────────────────────────────────────── */
.kr-pcard__media {
  position: relative;
  aspect-ratio: ${layout.mediaAspect};
  background: ${color.mediaPlaceholder};
  overflow: hidden;
  flex-shrink: 0;
}
.kr-pcard__image {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transition: transform ${timing.zoom}ms ${ease};
}
.kr-pcard:hover .kr-pcard__image { transform: scale(${layout.imageZoom}); }

/* Bright at rest; only a whisper of charcoal on hover. */
.kr-pcard__tint {
  position: absolute;
  inset: 0;
  background: ${color.mediaTint};
  opacity: 0;
  pointer-events: none;
  transition: opacity ${timing.hover}ms ${ease};
}
.kr-pcard:hover .kr-pcard__tint { opacity: 1; }

/* ── badges ───────────────────────────────────────────── */
.kr-pcard__badges {
  position: absolute;
  inset: ${spacing.badgeInset}px ${spacing.badgeInset}px auto ${spacing.badgeInset}px;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: ${spacing.badgeGap}px;
  pointer-events: none;
}
.kr-pcard__badge {
  padding: ${spacing.badgePaddingY}px ${spacing.badgePaddingX}px;
  border-radius: ${layout.badgeRadius}px;
  font-family: ${typography.badgeFamily};
  font-size: ${typography.badgeSize}px;
  font-weight: ${typography.badgeWeight};
  letter-spacing: ${typography.badgeTracking};
  text-transform: uppercase;
  line-height: 1;
  white-space: nowrap;
}
.kr-pcard__badge--featured {
  background: ${color.badgeFeaturedBackground};
  color: ${color.badgeFeaturedText};
}
.kr-pcard__badge--status {
  margin-left: auto;
  background: ${color.badgeStatusBackground};
  color: ${color.badgeStatusText};
  -webkit-backdrop-filter: blur(6px);
  backdrop-filter: blur(6px);
}

/* ── body ─────────────────────────────────────────────── */
.kr-pcard__body {
  display: flex;
  flex-direction: column;
  flex: 1;
  padding: ${spacing.bodyPadding}px;
}

.kr-pcard__type {
  margin: 0 0 ${spacing.typeGap}px;
  color: ${color.type};
  font-family: ${typography.typeFamily};
  font-size: ${typography.typeSize}px;
  font-weight: ${typography.typeWeight};
  letter-spacing: ${typography.typeTracking};
  text-transform: uppercase;
}

.kr-pcard__title {
  margin: 0 0 ${spacing.titleGap}px;
  color: ${color.title};
  font-family: ${typography.titleFamily};
  font-size: ${typography.titleSize};
  font-weight: ${typography.titleWeight};
  letter-spacing: ${typography.titleTracking};
  line-height: 1.25;
  /* One line, always — a wrapping name must not lengthen one card. */
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.kr-pcard__link {
  color: inherit;
  text-decoration: none;
  transition: color ${timing.hover}ms ${ease};
}
.kr-pcard:hover .kr-pcard__link { color: ${color.titleHover}; }
/* Stretched link: correct semantics (the accessible name is the property
   title) while the entire card remains clickable. */
.kr-pcard__link::after {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 1;
}
.kr-pcard__link:focus-visible { outline: none; }

.kr-pcard__location {
  display: flex;
  align-items: center;
  gap: 7px;
  margin: 0 0 ${spacing.locationGap}px;
  color: ${color.locationText};
  font-family: ${typography.locationFamily};
  font-size: ${typography.locationSize}px;
  font-weight: ${typography.locationWeight};
  min-width: 0;
}
.kr-pcard__location-icon {
  display: inline-flex;
  color: ${color.locationIcon};
  flex-shrink: 0;
}
.kr-pcard__location-text {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ── stats ────────────────────────────────────────────────
   One clear row, not a header row plus an icon row. */
.kr-pcard__stats {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: ${spacing.statsItemGap}px;
  margin: 0 0 ${spacing.statsGap}px;
  padding: 0;
  list-style: none;
}
.kr-pcard__stat {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: ${color.statText};
  font-family: ${typography.statFamily};
  font-size: ${typography.statSize}px;
  font-weight: ${typography.statWeight};
  white-space: nowrap;
}
.kr-pcard__stat-icon {
  display: inline-flex;
  color: ${color.statIcon};
  flex-shrink: 0;
}

/* ── footer ───────────────────────────────────────────────
   margin-top: auto pins rent and CTA to a shared baseline.

   It wraps rather than overflowing. Both children carry white-space: nowrap,
   so in a card too narrow to seat them side by side they used to run straight
   through the card's padding and get clipped by its border - the CTA read
   "VIEW PROPERT". Wrapping drops the CTA onto its own line instead, which is
   merely taller rather than broken. */
.kr-pcard__footer {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  justify-content: space-between;
  gap: 8px 14px;
  margin-top: auto;
  padding-top: ${spacing.footerGap}px;
  border-top: 1px solid ${color.statDivider};
}

.kr-pcard__rent {
  margin: 0;
  display: flex;
  align-items: baseline;
  gap: 5px;
  color: ${color.rent};
  font-family: ${typography.rentFamily};
  font-size: ${typography.rentSize}px;
  font-weight: ${typography.rentWeight};
  line-height: 1;
}
.kr-pcard__rent-period {
  color: ${color.rentPeriod};
  font-family: ${typography.rentPeriodFamily};
  font-size: ${typography.rentPeriodSize}px;
  font-weight: ${typography.rentPeriodWeight};
}

.kr-pcard__cta {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: ${color.cta};
  font-family: ${typography.ctaFamily};
  font-size: ${typography.ctaSize}px;
  font-weight: ${typography.ctaWeight};
  letter-spacing: ${typography.ctaTracking};
  text-transform: uppercase;
  white-space: nowrap;
  transition: color ${timing.hover}ms ${ease};
}
.kr-pcard:hover .kr-pcard__cta { color: ${color.ctaHover}; }
.kr-pcard__cta-arrow { transition: transform ${timing.hover}ms ${ease}; }
.kr-pcard:hover .kr-pcard__cta-arrow { transform: translateX(4px); }

/* ── list variant ─────────────────────────────────────────
   The same markup, reflowed. Search Results switches between this and the
   grid card with one prop, so there is no second component to maintain and
   no chance of the two drifting apart. */
.kr-pcard--list {
  flex-direction: row;
  align-items: stretch;
}
.kr-pcard--list .kr-pcard__media {
  flex: 0 0 ${layout.listMediaWidth};
  aspect-ratio: auto;
  min-height: ${layout.listMinHeight}px;
}
.kr-pcard--list .kr-pcard__body {
  flex: 1 1 auto;
  padding: ${spacing.listBodyPadding}px;
  min-width: 0;
}
/* Type and availability share a line here, where there is width for it. */
.kr-pcard--list .kr-pcard__type { margin-bottom: ${spacing.listTypeGap}px; }
.kr-pcard--list .kr-pcard__title { font-size: ${typography.listTitleSize}px; }

.kr-pcard__summary {
  display: none;
  margin: 0 0 ${spacing.listSummaryGap}px;
  color: ${color.summary};
  font-family: ${typography.locationFamily};
  font-size: ${typography.summarySize}px;
  line-height: 1.65;
  /* Two lines at most: a list row must not grow into an article. */
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

/* Below this width a side-by-side row squeezes both halves, so the list card
   becomes a stacked card again — compact, but never a tiny horizontal strip. */
@media (max-width: ${layout.listStackBelow}px) {
  .kr-pcard--list { flex-direction: column; }
  .kr-pcard--list .kr-pcard__media {
    flex: 0 0 auto;
    aspect-ratio: ${layout.mediaAspect};
    min-height: 0;
  }
  .kr-pcard--list .kr-pcard__body { padding: ${spacing.bodyPadding}px; }
  .kr-pcard--list .kr-pcard__title { font-size: ${typography.titleSize}px; }
}

@media (max-width: 520px) {
  .kr-pcard__body { padding: ${spacing.bodyPaddingCompact}px; }
  .kr-pcard__stats { gap: 12px; }
}

@media (prefers-reduced-motion: reduce) {
  .kr-pcard,
  .kr-pcard__image,
  .kr-pcard__tint,
  .kr-pcard__cta-arrow {
    transition-duration: .01ms;
  }
  .kr-pcard:hover { transform: none; }
  .kr-pcard:hover .kr-pcard__image { transform: none; }
  .kr-pcard:hover .kr-pcard__cta-arrow { transform: none; }
}
`;

const template: PropertyCardTemplate = {
  css,
  rootClass: "kr-pcard",
  labels,
  layout,
};

export default template;
